WITH p AS (SELECT coalesce(%s::text,'') ma_chi_tieu,coalesce(%s::text,'') trang_thai,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT row_number() OVER(ORDER BY q.ma_chi_tieu) stt,q.ma_chi_tieu,q.ten_chi_tieu,q.ten_chi_tieu2,q.ma_dvdl,q.ma_ccdc,q.kieu_gia_tri,q.gia_tri_mac_dinh,q.tan_suat_do,q.ky_hieu_ban_ve,q.min,q.max,q.khoang_fa,q.kieu_so_sanh,q.status,count(*) OVER() total FROM public.qcdmchitieu q CROSS JOIN s WHERE s.ok IS NOT NULL AND (s.ma_chi_tieu='' OR q.ma_chi_tieu=ANY(string_to_array(s.ma_chi_tieu,','))) AND (s.trang_thai='' OR q.status=s.trang_thai) AND (s.all_branch OR coalesce(q.ds_ma_dvcs,'')='' OR EXISTS(SELECT 1 FROM unnest(string_to_array(s.bs,',')) x WHERE x=ANY(string_to_array(q.ds_ma_dvcs,',')))) ORDER BY q.ma_chi_tieu LIMIT (SELECT lim FROM p);
